    "scripts": [
      {
        "code": "// Show only the selected tab's images\r\n    function showGalleryTab(tab) {\r\n      document.querySelectorAll('.gallery-item').forEach(item => {\r\n        if (item.getAttribute('data-category') === tab) {\r\n          item.classList.add('show');\r\n        } else {\r\n          item.classList.remove('show');\r\n        }\r\n      });\r\n    }\r\n\r\n    // On tab click\r\n    document.querySelectorAll('.gallery-tab').forEach(tabBtn => {\r\n      tabBtn.addEventListener('click', function() {\r\n        document.querySelectorAll('.gallery-tab').forEach(t => t.classList.remove('active'));\r\n        this.classList.add('active');\r\n        showGalleryTab(this.getAttribute('data-tab'));\r\n      });\r\n    });\r\n\r\n    // On page load, show only research images\r\n    document.addEventListener('DOMContentLoaded', function() {\r\n      showGalleryTab('research');\r\n    });",
        "src": ""
      }
    ]
