        "code": "{\r\n    \"@context\": \"https://schema.org\",\r\n    \"@type\": \"ScholarlyArticle\",\r\n    \"headline\": \"Loss Design and Architecture Selection for Long-Tailed Multi-Label Chest X-Ray Classification\",\r\n    \"description\": \"Systematic evaluation of loss functions, CNN architectures and post-training strategies for long-tailed multi-label CXR classification on the CXR-LT 2026 benchmark.\",\r\n    \"image\": \"https://nikhil-rao20.github.io/cxr-lt/media/cxr-lt-qualitative.png\",\r\n    \"datePublished\": \"2026-03-04\",\r\n    \"author\": {\r\n      \"@type\": \"Person\",\r\n      \"name\": \"Nikhileswara Rao Sulake\",\r\n      \"url\": \"https://nikhil-rao20.github.io\",\r\n      \"sameAs\": [\r\n        \"https://github.com/Nikhil-Rao20\",\r\n        \"https://linkedin.com/in/nikhil-rao20\"\r\n      ],\r\n      \"affiliation\": {\r\n        \"@type\": \"Organization\",\r\n        \"name\": \"RGUKT Nuzvid\"\r\n      }\r\n    },\r\n    \"publisher\": {\r\n      \"@type\": \"Person\",\r\n      \"name\": \"Nikhileswara Rao Sulake\",\r\n      \"url\": \"https://nikhil-rao20.github.io\"\r\n    },\r\n    \"mainEntityOfPage\": {\r\n      \"@type\": \"WebPage\",\r\n      \"@id\": \"https://nikhil-rao20.github.io/cxr-lt/\"\r\n    },\r\n    \"keywords\": [\"chest x-ray\", \"long-tailed classification\", \"multi-label learning\", \"deep learning\", \"class imbalance\", \"LDAM-DRW\", \"ConvNeXt\"],\r\n    \"about\": {\r\n      \"@type\": \"Thing\",\r\n      \"name\": \"Medical Image Classification\"\r\n    },\r\n    \"isAccessibleForFree\": true,\r\n    \"inLanguage\": \"en\"\r\n  }",
